mapper.insert:

	    SELECT
	        'PTPL'||
	        LPAD(NVL(TO_NUMBER(SUBSTR(MAX(POR_CODE), LENGTH('PTPL' ) + 1)), 0) + 1, 6, '0')
	    FROM PORTFOLIO

	INSERT INTO PORTFOLIO (
        POR_CODE
      , RESUME_NO
      , POR_NAME
	  , POR_START_DATE
	  , POR_END_DATE
	  , POR_INFORMATION
      , DELETE_DATE
      , POR_URL
    ) VALUES (
        #{porCode}
      , #{resumeNo}
      , #{porName}
      , REPLACE(#{porStartDate}, '-', '')
      , REPLACE(#{porEndDate}, '-', '')
      , #{porInformation}
      , #{deleteDate}
      , #{porUrl}
    )

mapper.update:
UPDATE PORTFOLIO
   SET RESUME_NO         = #{resumeNo}
     , POR_NAME          = #{porName}
     , POR_START_DATE    = REPLACE(#{porStartDate}, '-', '')
     , POR_END_DATE      = REPLACE(#{porEndDate}, '-', '')
     , POR_INFORMATION   = #{porInformation}
     , POR_URL   		 = #{porUrl}
 WHERE POR_CODE = #{porCode}

UPDATE PORTFOLIO
   SET RESUME_NO         = #{resumeNo}
     , POR_NAME          = #{porName}
     , POR_START_DATE    = REPLACE(#{porStartDate}, '-', '')
     , POR_END_DATE      = REPLACE(#{porEndDate}, '-', '')
     , POR_INFORMATION   = #{porInformation}
     , POR_URL   		 = #{porUrl}
     , DELETE_DATE       = SYSDATE
 WHERE POR_CODE = #{porCode}
